  async function api(path,body){
    const options={headers:{'Accept':'application/json'},credentials:'same-origin'};
    // Only reads time out here. Writes are never automatically aborted or replayed.
    const controller=body===undefined?new AbortController():null;
    const timeout=controller?setTimeout(()=>controller.abort(),20000):null;
    if(controller)options.signal=controller.signal;
    if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';if(state.token)options.headers['X-Transit-Token']=state.token;options.body=JSON.stringify(body);}
    try{const response=await fetch(path,options);if(!response.ok){let message=`Request failed (${response.status})`;try{const detail=(await response.json()).detail;message=typeof detail==='string'?detail:JSON.stringify(detail);}catch{}throw new Error(message);}return await response.json();}
    catch(error){if(error.name==='AbortError')throw new Error('Read request timed out after 20 seconds.');throw error;}
    finally{if(timeout!==null)clearTimeout(timeout);}
  }

