  function openTab(tab){if(!tabs[tab])tab='overview';state.tab=tab;document.querySelectorAll('.view').forEach(el=>{const active=el.id===`view-${tab}`;el.hidden=!active;el.classList.toggle('active',active);});document.querySelectorAll('[data-tab]').forEach(button=>{button.classList.toggle('active',button.dataset.tab===tab);if(button.dataset.tab===tab)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});$('page-title').innerHTML=esc(tabs[tab][0])+'<span class="heading-dot">.</span>';$('page-subtitle').textContent=tabs[tab][1];$('breadcrumb-current').textContent=tabs[tab][2];history.replaceState(null,'',`#${tab}`);renderCurrentTab();if(tab==='overview')requestAnimationFrame(resizeCanvas);onPollingViewChange();}
