  // Each endpoint has one completion-scheduled request. Explicit requests arriving
  // mid-flight wait for a subsequent fetch, so mutation refreshes cannot be lost.
  function createCompletionPoller({run,cadence,enabled,maxBackoff=60000,onError=()=>{},onSettled=()=>{}}){
    let timer=null,inFlight=null,pending=false,waiters=[],failures=0,lastCompletedAt=null,nextDueAt=null;
    const delay=()=>Math.min(maxBackoff,cadence()*2**Math.min(failures,8));
    function clear(){if(timer!==null)clearTimeout(timer);timer=null;nextDueAt=null;}
    function schedule(){
      clear();if(!enabled()||inFlight)return;
      if(pending){start();return;}
      const wait=lastCompletedAt===null?0:Math.max(0,lastCompletedAt+delay()-Date.now());
      nextDueAt=Date.now()+wait;timer=setTimeout(()=>{timer=null;nextDueAt=null;request();},wait);
    }
    function start(){
      if(inFlight||!enabled())return inFlight;
      clear();pending=false;const batch=waiters.splice(0);
      inFlight=(async()=>{let ok=false;try{await Promise.resolve().then(run);failures=0;ok=true;}catch(error){failures++;onError(error);}
        finally{lastCompletedAt=Date.now();inFlight=null;for(const resolve of batch)resolve(ok);schedule();onSettled();}
      })();return inFlight;
    }
    function request(force=false){
      let result;if(force){result=new Promise(resolve=>waiters.push(resolve));pending=true;}
      else if(inFlight)return inFlight;else pending=true;
      start();return result||inFlight||Promise.resolve(false);
    }
    function reschedule(immediate=false){clear();if(!enabled())return;if(immediate){request();return;}schedule();}
    return {request,reschedule,get failures(){return failures;},get pending(){return pending;},get running(){return !!inFlight;},get nextDueAt(){return nextDueAt;},get lastCompletedAt(){return lastCompletedAt;}};
  }
  const integrationViews=new Set(['connections','incidents']),visitedIntegrationViews=new Set();
  let freshnessTimer=null;
  const dashboardCadence=()=>state.data?.clock?.paused?15000:state.tab==='overview'?5000:10000;
  const pollingVisible=()=>state.pollingStarted&&!document.hidden;
  const integrationVisible=()=>pollingVisible()&&integrationViews.has(state.tab);
  const dashboardPoll=createCompletionPoller({run:fetchDashboard,cadence:dashboardCadence,enabled:pollingVisible,maxBackoff:60000,
    onError:error=>{$('connection-banner').textContent='City connection interrupted. Cached readings remain visible; retrying automatically. '+error.message;$('connection-banner').hidden=false;if(!state.data)$('map-loading').innerHTML='<span class="loading-ring"></span>Waiting for the city service…';},onSettled:updateFreshness});
  const integrationPoll=createCompletionPoller({run:fetchIntegrations,cadence:()=>30000,enabled:integrationVisible,maxBackoff:120000,
    onError:error=>{state.integrationError=error.message;},onSettled:updateFreshness});
  async function fetchDashboard(){
    const data=await api('/api/dashboard'),receivedAt=performance.now();
    if(state.data){state.previousPeople=new Map((state.data.people||[]).map(p=>[p.id,p]));state.previousVehicles=new Map((state.data.vehicles||[]).map(p=>[p.id,p]));state.previousTraffic=new Map((state.data.road_traffic?.vehicles||[]).map(p=>[p.id,p]));}
    const sampleGap=state.receivedAt?receivedAt-state.receivedAt:dashboardCadence();
    state.data=data;state.animationDuration=Math.max(1000,Math.min(5000,sampleGap));state.receivedAt=receivedAt;state.receivedWallAt=Date.now();
    const revision=data.workplace_revision??0;if(revision!==state.cityRevision&&!document.hidden)refreshCityCatalog(revision);
    for(const sensor of data.sensors||[]){const values=state.sensorHistory.get(sensor.id)||[];values.push(Number(sensor.value)||0);if(values.length>25)values.shift();state.sensorHistory.set(sensor.id,values);}
    renderDashboard();$('connection-banner').hidden=true;$('map-loading').hidden=true;
  }
  async function fetchIntegrations(){
    state.integrations=await api('/api/integrations/status');state.integrationReceivedAt=Date.now();state.integrationError=null;
    if(state.data&&state.tab==='connections')renderConnections();if(state.data&&state.tab==='incidents')renderIncidents();
  }
  function refresh(force=false){
    if(force&&integrationVisible())integrationPoll.request(true);
    return dashboardPoll.request(force);
  }
  function onPollingViewChange(){
    if(!state.pollingStarted)return;dashboardPoll.reschedule();
    const firstVisit=integrationViews.has(state.tab)&&!visitedIntegrationViews.has(state.tab);
    if(firstVisit)visitedIntegrationViews.add(state.tab);
    integrationPoll.reschedule(firstVisit);updateFreshness();
  }
  function updateFreshness(){
    if(!state.pollingStarted)return;
    const age=state.receivedWallAt?Math.max(0,Math.floor((Date.now()-state.receivedWallAt)/1000)):null;
    const stale=dashboardPoll.failures>0||(age!==null&&age>Math.max(15,dashboardCadence()/500));
    const badge=document.hidden?'UPDATES SUSPENDED':!state.data?'CONNECTING':stale?'STALE DATA':state.data.clock?.paused?'SIMULATION PAUSED':'LIVE SIMULATION';
    $('live-badge').innerHTML='<i></i>'+badge;$('map-live-label').innerHTML='<i></i>'+(document.hidden?'SUSPENDED':stale?'STALE':state.data?.clock?.paused?'PAUSED':'LIVE');
    const retry=dashboardPoll.nextDueAt?Math.max(0,Math.ceil((dashboardPoll.nextDueAt-Date.now())/1000)):null;
    $('last-sync').textContent=document.hidden?'Updates suspended while this tab is hidden':age===null?'Waiting for first update':`${stale?'Stale data · ':''}Updated ${age}s ago${dashboardPoll.failures?' · '+(dashboardPoll.running?'retrying now':retry!==null?'retry in '+retry+'s':'waiting to retry'):' · '+dashboardCadence()/1000+'s refresh interval'}`;
    for(const tab of integrationViews){let note=$('partner-freshness-'+tab);if(!note){note=document.createElement('div');note.id='partner-freshness-'+tab;note.className='connection-banner';note.setAttribute('role','status');$('view-'+tab).prepend(note);}
      const partnerAge=state.integrationReceivedAt?Math.max(0,Math.floor((Date.now()-state.integrationReceivedAt)/1000)):null;
      note.hidden=state.tab!==tab||(!integrationPoll.failures&&(partnerAge===null||partnerAge<=60));
      if(!note.hidden)note.textContent=`Partner data ${partnerAge===null?'is unavailable':'is stale · last updated '+partnerAge+'s ago'}. ${state.integrationError||'Refreshing when this view is active.'}`;
    }
  }
  function freshnessTick(){clearTimeout(freshnessTimer);freshnessTimer=null;updateFreshness();if(pollingVisible())freshnessTimer=setTimeout(freshnessTick,1000);}
  document.addEventListener('visibilitychange',()=>{
    if(!state.pollingStarted)return;dashboardPoll.reschedule(!document.hidden);integrationPoll.reschedule(!document.hidden);freshnessTick();
  });

  function setMetric(id,value){$(id).textContent=fmt(value);}
  function renderDashboard(){if(!state.controlsReady){['play-pause','speed','date-button','scenario-button'].forEach(id=>$(id).disabled=false);state.controlsReady=true;}const d=state.data,s=d.stats||{};setMetric('metric-people',s.active_people??d.people?.length);setMetric('metric-vehicles',d.vehicles?.length);setMetric('metric-arrivals',s.gateway_people_today??0);setMetric('metric-incidents',s.active_incidents??(d.incidents||[]).filter(i=>i.status!=='resolved').length);$('metric-people-note').textContent=`${fmt(s.moving_people??(d.people||[]).filter(p=>p.status==='moving').length)} moving · ${fmt(s.queued_people??0)} waiting`;$('metric-vehicles-note').textContent=`${(state.city?.routes||[]).length} routes across the region`;$('metric-arrivals-note').textContent='Modeled gateway travelers today';$('metric-incidents-note').textContent=s.active_incidents?'Response coordination active':'Monitoring the transit network';$('nav-incidents').textContent=fmt(s.active_incidents??0);const cruiseSummary=d.cruise_terminal;if(cruiseSummary&&cruiseSummary.enabled){const inPort=(cruiseSummary.ships||[]).filter(ship=>ship.status!=='departed').length;$('nav-cruise').hidden=!inPort;$('nav-cruise').textContent=fmt(inPort);if(state.cruiseLayer&&(state.tab==='overview'||state.tab==='cruise'))fetchCruiseDetail();}
    const clock=d.clock||{};$('map-live-label').innerHTML=`<i></i>${clock.paused?'PAUSED':'LIVE'}`;$('clock-time').textContent=shortTime(clock.iso);$('clock-date').textContent=dateLabel(clock.iso);$('live-badge').innerHTML=`<i></i>${clock.paused?'SIMULATION PAUSED':'LIVE SIMULATION'}`;$('play-pause').innerHTML=svg(clock.paused?'play':'pause');$('play-pause').setAttribute('aria-label',clock.paused?'Resume simulation':'Pause simulation');$('play-pause').title=clock.paused?'Resume simulation':'Pause simulation';if(!$('speed').querySelector(`option[value="${Number(clock.speed)}"]`)){const option=document.createElement('option');option.value=clock.speed;option.textContent=clock.speed+'× speed';$('speed').append(option);}$('speed').value=clock.speed;
    $('map-count').textContent=`${fmt((d.people||[]).length)} travelers · 1 dot = 1 modeled person`;$('map-caption').textContent=`Shared Northstar map ${state.basemap?.version||''} · ${fmt((state.city?.buildings||[]).length)} buildings · ${fmt((state.city?.roads||[]).length)} streets`;$('season-status').textContent=s.cruise_season?'IN SEASON':'OFF SEASON';$('sensor-count').textContent=`${fmt((d.sensors||[]).length)} SENSORS`;
    renderArrivalPreview();renderSensorPreview();renderModes();renderChart();renderTrafficOverview();const infra=d.infrastructure;if(infra){$('utility-disruption-button').disabled=false;const affected=infra.summary?.facilities_affected||0;$('nav-utilities').textContent=affected;$('nav-utilities').hidden=!affected;}const events=d.active_events||[];$('active-event-note').textContent=events.length?`${events[0].name} is shaping city travel${events.length>1?` · ${events.length-1} more active events`:''}`:'Regular city activity · explore the calendar for festivals, sports and seasonal events.';renderCurrentTab();}
  function cruiseStatusPill(status){const labels={scheduled:'Scheduled',holding:'Holding for berth',disembarking:'Disembarking',ashore:'Ashore',boarding:'All aboard',departed:'Departed'};const kind=status==='boarding'?'warning':status==='holding'?'critical':'info';return `<span class="status-pill ${kind}">${labels[status]||title(status)}</span>`;}
