    const cards=connections.length?connections:defaults;
    $('connections-grid').innerHTML=cards.map((c,index)=>{
      const reachable=c.reachable===true,label=c.name||c.id||c.source||defaults[index%2].name,departments=c.departments||[];
      const capacity=departments.reduce((n,d)=>n+(Number(d.capacity)||0),0),occupied=departments.reduce((n,d)=>n+(Number(d.occupied)||0),0);
      const observed=c.health_observed_at??c.observed_at;const ems=c.ems||{};const emsEntries=Object.entries(ems).filter(([,value])=>typeof value==='number').slice(0,3);
      return `<article class="connection-card"><div class="connection-card-top"><span class="connection-logo">${c.id==='hospital'?svg('hospital'):c.id==='911'?'911':svg('connections')}</span><span class="status-pill ${reachable?'normal':'disabled'}">${reachable?'Connected':esc(title(c.status||'Awaiting status'))}</span></div><h3>${esc(label)}</h3><p>${esc(c.description||defaults[index%2].description)}</p><div class="partner-meta"><span class="status-pill ${c.paused?'warning':'normal'}">${c.paused?'Source paused':c.paused===false?'Source running':'Clock unavailable'}</span>${c.source_sim_time?`<small>Source clock ${dateLabel(c.source_sim_time)} ${shortTime(c.source_sim_time)}</small>`:''}</div>${departments.length?`<div class="partner-capacity"><strong>${fmt(occupied)}<span> / ${fmt(capacity)}</span></strong><small>Occupied places across ${departments.length} departments</small></div>`:''}${emsEntries.length?`<p class="ems-summary">${emsEntries.map(([key,value])=>`${fmt(value)} ${esc(title(key))}`).join(' · ')}</p>`:''}${c.id==='911'&&c.dispatch_configured===false?'<p class="inline-warning">Dispatch token is not configured.</p>':''}${c.error?`<p class="inline-warning">${esc(c.error)}</p>`:''}${observed?`<code>Health observed ${dateLabel(observed)} ${shortTime(observed)}</code>`:''}${c.endpoint_observations?.departments?.observed_at?`<code>Capacity observed ${dateLabel(c.endpoint_observations.departments.observed_at)} ${shortTime(c.endpoint_observations.departments.observed_at)}</code>`:''}</article>`;
    }).join('')+`<article class="connection-card"><div class="connection-card-top"><span class="connection-logo">${svg('connections')}</span><span class="status-pill normal">API ready</span></div><h3>Your city systems</h3><p>Connect other simulators through authenticated reports and the MCP interface.</p><code>POST /api/integrations/reports</code><p class="developer-note" style="margin:16px 0 0">Partner clocks stay independent. Reports include their source time and the time transit observed them.</p></article>`;
    $('api-endpoint').textContent=location.origin+'/api';$('mcp-endpoint').textContent=`http://${location.hostname==='localhost'?'localhost':location.hostname}:8826/mcp`;
